# --------------------------------------------------------------------------- #
# Modelo de dados
# --------------------------------------------------------------------------- #
@dataclass
class Story:
    persona: str = "usuário"
    action: str = "utilizar a funcionalidade"
    benefit: str = "atingir seu objetivo"
    criteria: list[str] = field(default_factory=list)
    title: str = "Funcionalidade"


# --------------------------------------------------------------------------- #
# Parser (motor baseado em regras)
# --------------------------------------------------------------------------- #
STORY_RE = re.compile(
    r"como\s+(?:um|uma|o|a)?\s*(?P<persona>.+?)[,\n]\s*"
    r"(?:eu\s+)?(?:quero|gostaria de|desejo|preciso)\s+(?P<action>.+?)"
    r"(?:[,\n]\s*(?:para que|para|a fim de)\s+(?P<benefit>.+?))?(?:\.|\n|$)",
    re.IGNORECASE | re.DOTALL,
)
BULLET_RE = re.compile(r"^\s*(?:[-*•]|\d+[.)]|CA\d*[:.-]?)\s*(.+)$", re.IGNORECASE)


def _clean(text: str) -> str:
    return re.sub(r"\s+", " ", text).strip(" .,;:")


def parse_story(raw: str) -> Story:
    story = Story()
    m = STORY_RE.search(raw)
    if m:
        story.persona = _clean(m.group("persona"))
        story.action = _clean(m.group("action"))
        if m.group("benefit"):
            story.benefit = _clean(m.group("benefit"))

    # Critérios: linhas com marcadores ou após "critérios de aceitação"
    lines = raw.splitlines()
    in_criteria = False
    for line in lines:
        low = line.lower()
        if "critério" in low or "criterio" in low or "regra" in low:
            in_criteria = True
            continue
        b = BULLET_RE.match(line)
        if b:
            story.criteria.append(_clean(b.group(1)))
        elif in_criteria and line.strip():
            story.criteria.append(_clean(line))

    # Fallback: frases do texto
    if not story.criteria:
        sentences = [s for s in re.split(r"(?<=[.!?])\s+", raw) if len(s.split()) > 3]
        story.criteria = [_clean(s) for s in sentences if not STORY_RE.match(s)][:6]
    if not story.criteria:
        story.criteria = [f"O sistema deve permitir {story.action}"]

    story.title = story.action[:1].upper() + story.action[1:]
    return story


NEGATIVE_HINTS = ("inválid", "erro", "não deve", "bloque", "negad", "falha", "obrigat", "vazio")


def is_negative(c: str) -> bool:
    return any(h in c.lower() for h in NEGATIVE_HINTS)


def criterion_to_given_when_then(c: str, story: Story) -> tuple[str, str, str]:
    """Divide um critério em contexto/ação/resultado de forma heurística."""
    parts = re.split(r"\b(?:quando|ao|se)\b", c, maxsplit=1, flags=re.IGNORECASE)
    if len(parts) == 2:
        left, rest = parts
        res = re.split(r"\b(?:então|entao|deve|o sistema)\b", rest, maxsplit=1, flags=re.IGNORECASE)
        when = _clean(res[0])
        then = _clean(res[1]) if len(res) == 2 else c
        given = _clean(left) or f"que o {story.persona} está autenticado no sistema"
        return given, when, then
    return (
        f"que o {story.persona} está na tela da funcionalidade",
        f"ele tenta {story.action}",
        c[0].lower() + c[1:] if c else c,
    )


# --------------------------------------------------------------------------- #
# Geração de PDF (fpdf2)
# --------------------------------------------------------------------------- #
def _pdf_safe(text: str) -> str:
    """Normalize Markdown and punctuation without printing emoji placeholders."""
    import html
    text = html.unescape(text)
    text = re.sub(r"\*\*(.+?)\*\*", r"\1", text)
    text = re.sub(r"`([^`]+)`", r"\1", text)
    for source, replacement in {
        "—": " - ", "–": "-", "“": '"', "”": '"', "‘": "'", "’": "'",
        "…": "...", "\u00a0": " ", "→": " -> ", "≥": ">=", "≤": "<=",
    }.items():
        text = text.replace(source, replacement)
    return text.encode("latin-1", "ignore").decode("latin-1").strip()


IMAGE_CACHE_LIMIT_BYTES = 150 * 1024 * 1024
THUMB_CACHE_LIMIT_BYTES = 60 * 1024 * 1024


def cache_put(cache, key, value, limit_bytes):
    """Guarda no cache da sessão e descarta as entradas mais antigas se passar do limite de memória."""
    cache[key] = value
    while len(cache) > 1 and sum(len(item) for item in cache.values()) > limit_bytes:
        cache.pop(next(iter(cache)))


def prepare_client_logo(uploaded_bytes: bytes) -> bytes:
    """Valida e normaliza a imagem. O resultado fica guardado na sessão de quem usa o app,
    para a mesma imagem não ser reprocessada a cada clique (nada é compartilhado entre pessoas)."""
    cache = st.session_state.setdefault('_image_cache', {})
    key = hashlib.blake2b(uploaded_bytes, digest_size=16).hexdigest()
    cached = cache.get(key)
    if cached is not None:
        return cached
    result = _normalize_image(uploaded_bytes)
    cache_put(cache, key, result, IMAGE_CACHE_LIMIT_BYTES)
    return result


def _normalize_image(uploaded_bytes: bytes) -> bytes:
    """Validate and normalize an uploaded bitmap without companion files."""
    from PIL import Image, ImageOps, UnidentifiedImageError
    import warnings
    if len(uploaded_bytes) > 10 * 1024 * 1024:
        raise ValueError("A logo deve ter no máximo 10 MB.")
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("error", Image.DecompressionBombWarning)
            with Image.open(io.BytesIO(uploaded_bytes)) as image:
                if image.format not in ("PNG", "JPEG"):
                    raise ValueError("Envie uma imagem PNG ou JPG válida.")
                image = ImageOps.exif_transpose(image)
                image.thumbnail((1600, 1600))
                image = image.convert("RGBA")
                output = io.BytesIO()
                image.save(output, format="PNG")
                return output.getvalue()
    except (UnidentifiedImageError, OSError, Image.DecompressionBombError,
            Image.DecompressionBombWarning) as exc:
        raise ValueError("Não foi possível ler a logo. Envie outra imagem PNG ou JPG.") from exc


def image_thumbnail(image_bytes: bytes, width: int) -> bytes:
    """Miniatura JPEG já na largura exibida. O Streamlit só reaproveita a imagem sem refazê-la quando ela
    chega na largura e no formato certos; por isso a miniatura é criada uma vez e guardada na sessão."""
    from PIL import Image
    cache = st.session_state.setdefault('_thumb_cache', {})
    key = ('raw', hashlib.blake2b(image_bytes, digest_size=16).hexdigest(), width)
    cached = cache.get(key)
    if cached is not None:
        return cached
    with Image.open(io.BytesIO(image_bytes)) as source:
        source.load()
        rgba = source.convert('RGBA')
    flat = Image.new('RGB', rgba.size, (255, 255, 255))  # fundo branco para PNGs com transparência
    flat.paste(rgba, mask=rgba.split()[3])
    if flat.width > width:
        flat = flat.resize((width, max(1, round(flat.height * width / flat.width))), Image.Resampling.LANCZOS)
    out = io.BytesIO()
    flat.save(out, 'JPEG', quality=88, optimize=True, subsampling=0)
    thumb = out.getvalue()
    cache_put(cache, key, thumb, THUMB_CACHE_LIMIT_BYTES)
    return thumb


def evidence_thumbnail(ev, width: int) -> bytes:
    """Miniatura de uma evidência (dict com 'data' em base64). Lança ValueError se a imagem for inválida."""
    data = ev.get('data', '')
    cache = st.session_state.setdefault('_thumb_cache', {})
    key = ('b64', hashlib.blake2b(data.encode('ascii', 'ignore'), digest_size=16).hexdigest(), width)
    cached = cache.get(key)
    if cached is not None:
        return cached
    thumb = image_thumbnail(prepare_client_logo(base64.b64decode(data, validate=True)), width)
    cache_put(cache, key, thumb, THUMB_CACHE_LIMIT_BYTES)
    return thumb



def make_pdf(markdown_text: str, title: str = "Cenários de Teste", *,
             qa_name: str = "", project_name: str = "", sprint: str = "", pdf_date: str = "",
             client_logo: bytes | None = None, evidence_images: dict | None = None,
             sprint_summary: dict | None = None, company_logo: bytes | None = None,
             card_code: str = "", card_link: str = "", title_link: str = "") -> bytes:
    """Render edited scenarios as a readable A4 report, with real wrapping tables."""
    from fpdf import FPDF
    from fpdf.enums import MethodReturnValue
    from fpdf.fonts import FontFace

    # Report palette: neutral ink and paper, with one restrained blue accent.
    ink = (31, 41, 55)
    muted = (100, 116, 139)
    accent = (37, 99, 160)
    rule = (218, 225, 232)
    pale = (243, 246, 249)

    # Only the explicitly uploaded client image enters the report.
    logo_bytes = prepare_client_logo(client_logo) if client_logo else None
    company_bytes = prepare_client_logo(company_logo) if company_logo else None
    left_rows = [("Nome do QA", qa_name), ("Nome do projeto", project_name), ("Data", pdf_date)]
    right_rows = [("Sprint", sprint), ("Código do card", card_code.strip()), ("Link Jira/Azure", card_link.strip())]
    safe_card_link = card_link.strip() if re.match(r"^https?://[^\s]+$", card_link.strip(), re.I) else ""
    safe_title_link = title_link.strip() if re.match(r"^https?://\S+$", title_link.strip(), re.I) else ""

    class ScenarioPDF(FPDF):
        def header(self):
            self.set_y(14)
            self.set_font("helvetica", "B", 9)
            self.set_text_color(*muted)
            self.cell(0, 6, "DOCUMENTAÇÃO DE TESTES", new_x="LMARGIN", new_y="NEXT")
            top = self.get_y() + 3
            logo_width = 26
            pair_width = (self.epw - logo_width) / 2
            label_width = 27
            value_width = pair_width - label_width
            row_heights = []
            for (_, left_value), (_, right_value) in zip(left_rows, right_rows):
                self.set_font("helvetica", "", 8.5)
                h_left = self.multi_cell(value_width - 5, 4.2, _pdf_safe(left_value) or "-",
                                         dry_run=True, output=MethodReturnValue.HEIGHT)
                h_right = self.multi_cell(value_width - 5, 4.2, _pdf_safe(right_value) or "-",
                                          dry_run=True, output=MethodReturnValue.HEIGHT)
                row_heights.append(max(9, h_left + 5, h_right + 5))
            total_height = sum(row_heights)
            self.set_draw_color(*rule)
            self.set_line_width(0.2)
            self.rect(self.l_margin, top, logo_width, total_height)
            if logo_bytes:
                self.image(io.BytesIO(logo_bytes), x=self.l_margin + 4, y=top + 4,
                           w=logo_width - 8, h=total_height - 8, keep_aspect_ratio=True)
            else:
                self.set_xy(self.l_margin + 2, top + total_height / 2 - 3)
                self.set_font("helvetica", "", 7)
                self.set_text_color(*muted)
                self.multi_cell(logo_width - 4, 4, "Logo do cliente", align="C")
            y = top
            for row, height in enumerate(row_heights):
                for side, (label, value) in enumerate((left_rows[row], right_rows[row])):
                    x = self.l_margin + logo_width + side * pair_width
                    self.set_fill_color(*pale)
                    self.rect(x, y, label_width, height, style="DF")
                    self.rect(x + label_width, y, value_width, height)
                    self.set_xy(x + 2.5, y + 3)
                    self.set_font("helvetica", "B", 7)
                    self.set_text_color(*muted)
                    self.cell(label_width - 5, 4, label)
                    self.set_xy(x + label_width + 2.5, y + 3)
                    link_row = label == "Link Jira/Azure"
                    self.set_font("helvetica", "", 7 if link_row else 8.5)
                    self.set_text_color(*ink)
                    self.multi_cell(value_width - 5, 4.2, _pdf_safe(value) or "-",
                                    link=safe_card_link if link_row else "",
                                    new_x="LMARGIN", new_y="NEXT")
                y += height
            self.set_xy(self.l_margin, top + total_height + 9)

        def footer(self):
            self.set_y(-21)
            self.set_draw_color(*rule)
            self.set_line_width(0.2)
            self.line(self.l_margin, self.get_y(), self.w - self.r_margin, self.get_y())
            text_x = self.l_margin
            if company_bytes:
                self.image(io.BytesIO(company_bytes), x=self.l_margin, y=self.h - 18.5,
                           w=38, h=11, keep_aspect_ratio=True)
                text_x = self.l_margin + 42
            self.set_xy(text_x, -15)
            self.set_font("helvetica", "", 8)
            self.set_text_color(*muted)
            self.cell(self.w - self.r_margin - text_x - 40, 5, "Documentação de testes")
            self.cell(40, 5, f"Página {self.page_no()} de {{nb}}", align="R")

    pdf = ScenarioPDF(format="A4")
    pdf.set_margins(18, 28, 18)
    pdf.set_auto_page_break(auto=True, margin=27)
    pdf.alias_nb_pages()
    pdf.set_title(_pdf_safe(title))
    pdf.set_author(_pdf_safe(qa_name))
    pdf.add_page()

    def write(text, size=10, bold=False, color=ink, gap=2, keep_next=0, link=""):
        safe = _pdf_safe(text)
        if not safe:
            return
        pdf.set_font("helvetica", "B" if bold else "", size)
        height = pdf.multi_cell(pdf.epw, size * 0.49, safe, dry_run=True,
                                output=MethodReturnValue.HEIGHT)
        if pdf.will_page_break(height + keep_next):
            pdf.add_page()
        pdf.set_font("helvetica", "B" if bold else "", size)
        pdf.set_text_color(*color)
        pdf.multi_cell(pdf.epw, size * 0.49, safe, align="L", new_x="LMARGIN", new_y="NEXT", link=link)
        pdf.ln(gap)

    write(title, size=23, bold=True, gap=7, keep_next=18, link=safe_title_link)
    if sprint_summary and sprint_summary.get('total'):
        write('Resumo da sprint', size=14, bold=True, gap=5, keep_next=95)
        counts = sprint_summary.get('counts', {})
        cards = [('Total', sprint_summary['total'], ink), ('Aprovado', counts.get('Aprovado', 0), (22, 120, 70)),
                 ('Reprovado', counts.get('Reprovado', 0), (178, 45, 48)),
                 ('Bloqueado', counts.get('Bloqueado', 0), (176, 122, 4)),
                 ('Não executado', counts.get('Não executado', 0), muted)]
        card_width = (pdf.epw - 4 * 3) / 5
        card_height = 16
        x = pdf.l_margin
        top = pdf.get_y()
        for label, value, color in cards:
            pdf.set_fill_color(*pale)
            pdf.set_draw_color(*rule)
            pdf.set_line_width(0.2)
            pdf.rect(x, top, card_width, card_height, style='DF')
            pdf.set_xy(x, top + 1.5)
            pdf.set_font('helvetica', '', 7.5)
            pdf.set_text_color(*muted)
            pdf.cell(card_width, 4.5, _pdf_safe(label), align='C')
            pdf.set_xy(x, top + 6)
            pdf.set_font('helvetica', 'B', 12)
            pdf.set_text_color(*color)
            pdf.cell(card_width, 6, str(value), align='C')
            x += card_width + 3
        pdf.set_y(top + card_height + 6)
        write(f"{sprint_summary.get('pass_rate', 0)}% de aprovação entre os "
              f"{sprint_summary.get('executed', 0)} cenários executados de {sprint_summary['total']}.",
              size=9, color=muted, gap=4)
        bar_max = pdf.epw - 56
        for label, value, color in cards[1:]:
            y = pdf.get_y()
            pdf.set_xy(pdf.l_margin, y)
            pdf.set_font('helvetica', '', 8.5)
            pdf.set_text_color(*muted)
            pdf.cell(26, 5.5, _pdf_safe(label))
            pdf.set_fill_color(*pale)
            pdf.rect(pdf.l_margin + 26, y + 0.5, bar_max, 4.5, style='F')
            if value:
                pdf.set_fill_color(*color)
                pdf.rect(pdf.l_margin + 26, y + 0.5, bar_max * value / sprint_summary['total'], 4.5, style='F')
            pdf.set_xy(pdf.l_margin + 26 + bar_max + 3, y)
            pdf.set_font('helvetica', '', 8.5)
            pdf.set_text_color(*ink)
            pdf.cell(20, 5.5, str(value))
            pdf.set_y(y + 7)
        pdf.ln(4)
    lines = markdown_text.splitlines()
    if lines and lines[0].strip() == '## ' + title:
        lines = lines[1:]
    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line:
            pdf.ln(2)
            i += 1
            continue
        evidence_match = re.fullmatch(r"\[\[QA_EVIDENCE:([a-f0-9]+)\]\]", line)
        if evidence_match:
            image_data = (evidence_images or {}).get(evidence_match.group(1))
            if image_data:
                image_data = prepare_client_logo(image_data)
                from PIL import Image
                with Image.open(io.BytesIO(image_data)) as image:
                    width, height = image.size
                display_width = min(pdf.epw, 150)
                display_height = display_width * height / width
                if display_height > 95:
                    display_width *= 95 / display_height
                    display_height = 95
                if pdf.will_page_break(display_height + 5):
                    pdf.add_page()
                pdf.image(io.BytesIO(image_data), x=pdf.l_margin, y=pdf.get_y(), w=display_width, h=display_height)
                pdf.set_y(pdf.get_y() + display_height + 5)
            i += 1
            continue
        if line.startswith("```") or line.startswith("# language:"):
            i += 1
            continue
        if line.startswith("|"):
            rows = []
            while i < len(lines) and lines[i].strip().startswith("|"):
                cells = re.split(r"(?<!\\)\|", lines[i].strip().strip("|"))
                cells = [_pdf_safe(cell.replace(r"\|", "|").replace("<br>", " ")) for cell in cells]
                if not all(re.fullmatch(r":?-{2,}:?", c.replace(" ", "")) for c in cells):
                    rows.append(cells)
                i += 1
            if rows:
                columns = max(len(row) for row in rows)
                widths = (0.09, 0.45, 0.46) if columns == 3 else tuple(1 / columns for _ in range(columns))
                pdf.set_font("helvetica", "", 9)
                pdf.set_text_color(*ink)
                pdf.set_draw_color(*rule)
                pdf.set_line_width(0.15)
                with pdf.table(
                    col_widths=widths, width=pdf.epw, line_height=4.7,
                    padding=2.3, borders_layout="HORIZONTAL_LINES",
                    headings_style=FontFace(emphasis="BOLD", color=ink, fill_color=pale),
                    cell_fill_color=pale, cell_fill_mode="ROWS",
                    repeat_headings=1, text_align="LEFT",
                ) as table:
                    for cells in rows:
                        row = table.row()
                        for cell in cells + [""] * (columns - len(cells)):
                            row.cell(cell)
                pdf.ln(4)
            continue
        heading = re.match(r"^(#{1,6})\s+(.+)$", line)
        if heading:
            level = len(heading.group(1))
            pdf.ln(3)
            reserve = 18
            if re.match(r"CT\d+", _pdf_safe(heading.group(2))):
                reserve = 65
                for upcoming in lines[i + 1:]:
                    if upcoming.strip().startswith("### "):
                        break
                    if upcoming.strip().startswith("| 1 |"):
                        cells = upcoming.strip().strip("|").split("|")
                        pdf.set_font("helvetica", "", 9)
                        heights = [pdf.multi_cell(pdf.epw * width - 4.6, 4.7,
                                   _pdf_safe(cell), dry_run=True,
                                   output=MethodReturnValue.HEIGHT)
                                   for cell, width in zip(cells, (0.09, 0.45, 0.46))]
                        reserve = min(155, 45 + max(heights, default=5))
                        break
            write(heading.group(2), size=14 if level <= 2 else 11.5,
                  bold=True, color=ink if level <= 2 else accent, gap=3, keep_next=reserve)
        elif line.startswith(("Funcionalidade:", "Cenário:", "Esquema do Cenário:")):
            pdf.ln(3)
            write(line, size=13 if line.startswith("Funcionalidade:") else 11.5,
                  bold=True, color=accent, gap=3, keep_next=18)
        elif line.startswith("@"):
            # Keep scenario tags with their title and the first step.
            write(line, size=8, color=muted, gap=1, keep_next=32)
        elif line.startswith(("Contexto:", "Exemplos:")):
            write(line, size=10, bold=True, gap=2, keep_next=45 if line.startswith("Exemplos:") else 14)
        elif re.match(r"^\*\*CT\d+", line):
            match = re.match(r"^\*\*(CT\d+[.:]?)\*\*\s*(.*)", line)
            if match:
                pdf.ln(3)
                write(match.group(1).rstrip(".:"), size=11.5, bold=True,
                      color=accent, gap=2, keep_next=15)
                write(match.group(2), gap=4)
            else:
                write(line)
        elif line.startswith(">"):
            pdf.ln(3)
            write(line.lstrip("> "), bold=True, gap=4)
        elif line.startswith(("**Tipo:", "**Prioridade:")):
            write(line, size=9, color=muted, gap=3)
        else:
            write(line, gap=2)
        i += 1
    return bytes(pdf.output())


# --------------------------------------------------------------------------- #
# Botão de cópia
# --------------------------------------------------------------------------- #
def copy_button(text: str, key: str, label: str = 'Copiar cenários') -> None:
    payload = json.dumps(text).replace("<", "\\u003c")
    components.html(
        f"""
        <button id="btn-{key}" style="background:#fff;color:#161616;border:1px solid #dfe2e6;border-radius:6px;
          padding:12px 14px;font-weight:600;cursor:pointer;font-family:sans-serif;">
          {label}</button>
        <span id="ok-{key}" style="margin-left:10px;font-family:sans-serif;color:#626262;"></span>
        <script>
          document.getElementById("btn-{key}").onclick = async () => {{
            const t = {payload};
            try {{ await navigator.clipboard.writeText(t); }}
            catch(e) {{ const a=document.createElement('textarea'); a.value=t;
              document.body.appendChild(a); a.select(); document.execCommand('copy'); a.remove(); }}
            document.getElementById("ok-{key}").innerText = "Copiado!";
            setTimeout(()=>document.getElementById("ok-{key}").innerText="", 2000);
          }};
        </script>
        """,
        height=55,
    )


# --------------------------------------------------------------------------- #
# Structured scenarios, coverage, execution, CSV and portable snapshot history
# --------------------------------------------------------------------------- #
import csv
import uuid
from pathlib import Path

STATUSES = ('Não executado', 'Aprovado', 'Reprovado', 'Bloqueado')
KINDS = ('Positivo', 'Negativo', 'Limite')
DRAFT_PLACEHOLDER = 'A definir pelo QA'


def new_scenario(title='', *, criterion_ids=None, precondition='', steps='', expected='', kind='Positivo'):
    return dict(id=uuid.uuid4().hex, title=title, criterion_ids=list(criterion_ids or []),
                precondition=precondition, steps=steps, expected=expected, kind=kind,
                priority='Média', status='Não executado', observations='', evidence=[], bug={}, retests=[])


def build_scenarios(story):
    scenarios = []
    for i, criterion in enumerate(story.criteria):
        given, when, then = criterion_to_given_when_then(criterion, story)
        scenario = new_scenario(criterion[:120], criterion_ids=[i], precondition=given,
                                steps=when, expected=then,
                                kind='Negativo' if is_negative(criterion) else 'Positivo')
        scenario['priority'] = 'Alta' if i < 2 else 'Média'
        scenarios.append(scenario)
    return scenarios


def new_step(action='', expected=''):
    return dict(id=uuid.uuid4().hex, action=action, expected=expected, status='Não executado',
                observations='', evidence=[], auto_blocked=False)


def e2e_sync_text(s):
    """Mantém steps/expected (usados nas exportações) a partir das etapas do fluxo."""
    flow = s['flow']
    s['steps'] = '\n'.join(step['action'].strip() for step in flow if step['action'].strip())
    s['expected'] = '\n'.join(step['expected'].strip() for step in flow if step['expected'].strip())


def e2e_derived_status(flow):
    statuses = [step['status'] for step in flow]
    if 'Reprovado' in statuses:
        return 'Reprovado'
    if 'Bloqueado' in statuses:
        return 'Bloqueado'
    if statuses and all(status == 'Aprovado' for status in statuses):
        return 'Aprovado'
    return 'Não executado'


def e2e_refresh_blocks(flow):
    """Depois de uma etapa reprovada, as seguintes ainda não executadas ficam Bloqueadas."""
    for step in flow:
        if step.get('auto_blocked'):
            step['status'], step['auto_blocked'] = 'Não executado', False
    failed = False
    for step in flow:
        if failed and step['status'] == 'Não executado':
            step['status'], step['auto_blocked'] = 'Bloqueado', True
        if step['status'] == 'Reprovado':
            failed = True


def e2e_steps_editable(s):
    return not s.get('bug') and not s.get('retests')


def e2e_recompute(s):
    """Recalcula status, observações e evidências do teste a partir das etapas."""
    e2e_sync_text(s)
    if not e2e_steps_editable(s):
        return
    e2e_refresh_blocks(s['flow'])
    s['status'] = e2e_derived_status(s['flow'])
    notes = [f'Etapa {n} ({step["status"]}): {step["observations"].strip()}'
             for n, step in enumerate(s['flow'], 1)
             if step['status'] in ('Reprovado', 'Bloqueado') and not step.get('auto_blocked')
             and step['observations'].strip()]
    s['observations'] = '\n'.join(notes)
    s['evidence'] = [ev for step in s['flow'] for ev in step.get('evidence', [])]


def e2e_apply_steps(row, step_changes):
    for step in row['flow']:
        change = step_changes.get(step['id'])
        if change is None:
            continue
        new_status = change.get('status', step['status'])
        if new_status not in STATUSES:
            raise ValueError('Status de etapa inválido.')
        if not (step.get('auto_blocked') and new_status == step['status']):
            step['status'], step['auto_blocked'] = new_status, False
        step['observations'] = change.get('observations', step['observations'])
        removed = set(change.get('remove_evidence', []))
        step['evidence'] = [ev for ev in step.get('evidence', []) if ev['id'] not in removed]
        for ev in change.get('evidence', []):
            image = prepare_client_logo(base64.b64decode(ev['data'], validate=True))
            step['evidence'].append(dict(id=uuid.uuid4().hex, name=Path(ev['name']).name,
                                         data=base64.b64encode(image).decode()))
    e2e_recompute(row)


def e2e_progress(s):
    flow = s.get('flow') or []
    if flow and effective_status(s) == 'Aprovado':
        return len(flow), len(flow)
    return sum(step['status'] == 'Aprovado' for step in flow), len(flow)


def new_e2e_scenario(title='', precondition=''):
    scenario = new_scenario(title, precondition=precondition, kind='Positivo')
    scenario['priority'] = 'Alta'
    scenario['flow'] = [new_step()]
    e2e_sync_text(scenario)
    return scenario


def build_e2e_scenarios(raw=''):
    """Modelo E2E: um teste com título geral e as etapas digitadas pelo QA (não depende de critérios)."""
    match = STORY_RE.search(raw or '')
    if match:
        name = _clean(match.group('action'))
        name = name[:1].upper() + name[1:]
    else:
        name = next((line.strip() for line in (raw or '').splitlines() if line.strip()), '')[:100]
    return [new_e2e_scenario(f'E2E · {name or "Novo fluxo"}'[:120])]


def coverage_rows(criteria, scenarios):
    """Explicit links show traceability, not proof of semantic coverage."""
    return [{'criterion': criterion, 'linked': sum(i in s.get('criterion_ids', []) for s in scenarios)}
            for i, criterion in enumerate(criteria)]


def review_suggestions(criteria, scenarios):
    suggestions = []
    for i, criterion in enumerate(criteria):
        linked = [s for s in scenarios if i in s.get('criterion_ids', [])]
        if not linked:
            suggestions.append(dict(criterion_id=i, kind='Positivo', title='Critério sem cenário', criterion=criterion))
        for kind in ('Negativo', 'Limite'):
            if not any(s['kind'] == kind for s in linked):
                suggestions.append(dict(criterion_id=i, kind=kind,
                                        title=f'Revisar caso {kind.lower()}', criterion=criterion))
    return suggestions


def extract_requirement_text(filename: str, data: bytes) -> str:
    """Extrai texto de PDF ou Word para alimentar o campo de requisitos.

    Importações opcionais dentro da função: o app roda sem pypdf/python-docx
    até que o usuário importe um arquivo desses formatos."""
    name = filename.lower()
    if name.endswith('.pdf'):
        try:
            from pypdf import PdfReader
        except ImportError:
            raise ValueError('Para importar PDF, instale: pip install pypdf')
        try:
            text = '\n'.join((page.extract_text() or '') for page in PdfReader(io.BytesIO(data)).pages)
        except Exception:
            raise ValueError('Não consegui ler este PDF. Verifique se o arquivo não está corrompido ou protegido por senha.')
    elif name.endswith('.docx'):
        try:
            import docx
        except ImportError:
            raise ValueError('Para importar Word, instale: pip install python-docx')
        try:
            text = '\n'.join(paragraph.text for paragraph in docx.Document(io.BytesIO(data)).paragraphs)
        except Exception:
            raise ValueError('Não consegui ler este arquivo Word. Verifique se é um .docx válido (o formato antigo .doc não é suportado).')
    else:
        raise ValueError('Formato não suportado. Envie um arquivo .pdf ou .docx.')
    text = '\n'.join(line.rstrip() for line in text.splitlines() if line.strip())
    if not text.strip():
        raise ValueError('Não encontrei texto legível neste arquivo. Se for um PDF digitalizado (imagem), cole o texto manualmente.')
    return text


SEVERITIES = ('Baixa', 'Média', 'Alta', 'Crítica')
BUG_TOOL_EXPORTS = ('Jira', 'Azure DevOps')


def defect_draft(s):
    """Campos iniciais do defeito a partir do cenário reprovado; tudo editável na aba Defeitos."""
    flow = s.get('flow') or []
    failed_at = next((i for i, step in enumerate(flow) if step['status'] == 'Reprovado'), None)
    if failed_at is not None:
        step = flow[failed_at]
        return dict(title=f'{s["title"]} — falha na etapa {failed_at + 1}', severity='Alta', environment='',
                    precondition=s['precondition'],
                    steps='\n'.join(item['action'] for item in flow[:failed_at + 1] if item['action'].strip()),
                    expected=step['expected'], actual=step['observations'])
    return dict(title=s['title'], severity='Alta', environment='',
                precondition=s['precondition'], steps=s['steps'],
                expected=s['expected'], actual=s['observations'])


def ensure_bug(s):
    if not s.get('bug'):
        s['bug'] = defect_draft(s)
    s['bug'].setdefault('id', uuid.uuid4().hex)
    s['bug'].setdefault('external_ref', '')
    s['bug'].setdefault('external_link', '')
    s['bug'].setdefault('evidence', [])
    s['bug'].setdefault('original_failure', json.loads(json.dumps(dict(
        status=s['status'], observations=s['observations'], evidence=s.get('evidence', []),
        precondition=s['precondition'], steps=s['steps'], expected=s['expected'], flow=s.get('flow')))))
    s.setdefault('retests', [])
    return s['bug']


RETEST_STATUSES = ('Aprovado', 'Reprovado', 'Bloqueado')


def effective_status(s):
    attempts = s.get('retests', [])
    override = s.get('execution_override', {})
    if attempts and attempts[-1]['status'] == 'Aprovado' and override.get('retest_id') == attempts[-1]['id'] and override.get('status') in STATUSES:
        return override['status']
    return attempts[-1]['status'] if attempts else s['status']


def execution_status_editable(s):
    attempts = s.get('retests', [])
    return not s.get('bug') or bool(attempts and attempts[-1]['status'] == 'Aprovado')


def set_execution_status(s, status):
    if status not in STATUSES or not execution_status_editable(s):
        raise ValueError('Registre um reteste aprovado para liberar o status deste cenário.')
    attempts = s.get('retests', [])
    if attempts:
        s['execution_override'] = dict(status=status, retest_id=attempts[-1]['id'])
    else:
        s['status'] = status


def persist_execution(store, payload, changes, snapshot_id=None):
    """Validate a detached batch and save it before changing live records."""
    frozen = json.loads(json.dumps(payload))
    for row in frozen['scenarios']:
        change = changes.get(row['id'])
        if change is None:
            continue
        if row.get('flow') is not None:
            if e2e_steps_editable(row):
                e2e_apply_steps(row, change.get('steps', {}))
            else:
                status = change.get('status', effective_status(row))
                if execution_status_editable(row):
                    set_execution_status(row, status)
                elif status != effective_status(row):
                    raise ValueError('Registre um reteste aprovado para liberar o status deste cenário.')
            if row['status'] == 'Reprovado':
                ensure_bug(row)
            continue
        if execution_status_editable(row):
            set_execution_status(row, change['status'])
        elif change['status'] != effective_status(row):
            raise ValueError('Registre um reteste aprovado para liberar o status deste cenário.')
        if not row.get('retests'):
            row['observations'] = change.get('observations', row['observations'])
            removed = set(change.get('remove_evidence', []))
            row['evidence'] = [ev for ev in row.get('evidence', []) if ev['id'] not in removed]
            for ev in change.get('evidence', []):
                image = prepare_client_logo(base64.b64decode(ev['data'], validate=True))
                row['evidence'].append(dict(id=uuid.uuid4().hex, name=Path(ev['name']).name,
                                           data=base64.b64encode(image).decode()))
        if row['status'] == 'Reprovado':
            ensure_bug(row)
    identifier = save_snapshot(store, frozen, snapshot_id)
    return frozen, identifier


def execution_defect_evidence(s):
    """Keep execution provenance, including frozen original-failure attachments."""
    images = list(s.get('evidence', []))
    images += s.get('bug', {}).get('original_failure', {}).get('evidence', [])
    return list({image['id']: image for image in images}.values())


def persist_defect_evidence(store, payload, scenario_id, images, snapshot_id=None, remove_ids=None):
    """Validate and save detached defect attachments without rewriting execution or retests."""
    frozen = json.loads(json.dumps(payload))
    target = next((row for row in frozen['scenarios'] if row['id'] == scenario_id), None)
    if target is None or not (target.get('bug') or target['status'] == 'Reprovado'):
        raise ValueError('Defeito não encontrado para este cenário.')
    bug = ensure_bug(target)
    removed = set(remove_ids or [])
    attachments = [image for image in bug['evidence'] if image['id'] not in removed]
    for image in images:
        data = prepare_client_logo(base64.b64decode(image['data'], validate=True))
        attachments.append(dict(id=uuid.uuid4().hex, name=Path(image['name']).name,
                                data=base64.b64encode(data).decode()))
    bug['evidence'] = attachments
    identifier = save_snapshot(store, frozen, snapshot_id)
    return frozen, identifier


def defect_status(s):
    attempts = s.get('retests', [])
    if not attempts:
        return 'Aberto'
    return {'Aprovado': 'Resolvido', 'Reprovado': 'Reaberto', 'Bloqueado': 'Reteste bloqueado'}[attempts[-1]['status']]


def record_retest(s, status, *, actual, qa_name, environment='', version='', evidence=None,
                  project_name='', sprint=''):
    if status not in RETEST_STATUSES:
        raise ValueError('Selecione um resultado de reteste válido.')
    if not s.get('bug') and s['status'] != 'Reprovado':
        raise ValueError('O cenário precisa ter um defeito aberto antes do reteste.')
    if not actual.strip() or not qa_name.strip():
        raise ValueError('Preencha o QA responsável e o resultado obtido.')
    validated = []
    for image in evidence or []:
        data = prepare_client_logo(base64.b64decode(image['data'], validate=True))
        validated.append(dict(id=uuid.uuid4().hex, name=Path(image['name']).name,
                              data=base64.b64encode(data).decode()))
    bug = ensure_bug(s)
    if not s['retests']:
        bug['original_failure'] = json.loads(json.dumps(dict(
            status=s['status'], observations=s['observations'], evidence=s.get('evidence', []),
            precondition=s['precondition'], steps=s['steps'], expected=s['expected'], flow=s.get('flow'))))
    attempt = dict(id=uuid.uuid4().hex, scenario_id=s['id'], bug_id=bug['id'],
                   number=len(s['retests']) + 1, saved_at=datetime.now(timezone.utc).isoformat(),
                   status=status, actual=actual.strip(), qa_name=qa_name.strip(),
                   environment=environment, version=version, evidence=validated,
                   project_name=project_name, sprint=sprint,
                   scenario_title=s['title'], bug_title=bug['title'], external_ref=bug['external_ref'],
                   external_link=bug.get('external_link', ''),
                   precondition=bug['precondition'], steps=bug['steps'], expected=bug['expected'])
    s['retests'].append(attempt)
    s.pop('execution_override', None)
    return attempt


def persist_retest(store, payload, scenario_id, status, *, snapshot_id=None, **fields):
    # Work on a detached copy; neither an invalid image nor a failed write can
    # leave a partial attempt in the live scenario records.
    frozen = json.loads(json.dumps(payload))
    target = next((row for row in frozen['scenarios'] if row['id'] == scenario_id), None)
    if target is None:
        raise ValueError('Cenário não encontrado.')
    attempt = record_retest(target, status, **fields)
    snapshot_id = save_snapshot(store, frozen, snapshot_id)
    return frozen, attempt, snapshot_id


def retest_markdown(scenarios, *, evidence_refs=False):
    lines = []
    for s in scenarios:
        for attempt in s.get('retests', []):
            card = attempt['external_ref'] or attempt.get('external_link') or '-'
            if attempt.get('external_ref') and attempt.get('external_link'):
                card = f'{attempt["external_ref"]} ({attempt["external_link"]})'
            lines += [f'### Reteste {attempt["number"]} — {attempt["scenario_title"]}',
                      f'**Defeito:** {attempt["bug_title"]} | **Card do bug:** {card}',
                      f'**Data (UTC):** {attempt["saved_at"]}',
                      f'**Projeto:** {attempt["project_name"]} | **Sprint:** {attempt["sprint"]}',
                      f'**QA:** {attempt["qa_name"]} | **Ambiente:** {attempt["environment"] or "-"} | **Versão:** {attempt["version"] or "-"}',
                      f'**Status:** {attempt["status"]}',
                      f'**Pré-condições:** {attempt["precondition"]}',
                      '**Passos:**', steps_to_numbered(attempt['steps']),
                      f'**Resultado esperado:** {attempt["expected"]}',
                      f'**Resultado obtido:** {attempt["actual"]}']
            for ev in attempt['evidence']:
                lines.append(f'**Evidência:** {ev["name"]}')
                if evidence_refs:
                    lines.append(f'[[QA_EVIDENCE:{ev["id"]}]]')
            lines.append('')
    return '\n\n'.join(lines)


def display_evidence(images, *, caption_prefix='', width=280):
    for ev in images:
        try:
            st.image(evidence_thumbnail(ev, width), caption=caption_prefix + ev.get('name', 'Evidência'),
                     width=width, output_format='JPEG')
        except (ValueError, TypeError):
            st.warning(f'Não foi possível abrir a imagem {ev.get("name", "Evidência")}. Anexe novamente o arquivo original.')


def display_retest_history(s):
    for attempt in s.get('retests', []):
        with st.expander(f'Tentativa {attempt["number"]} · {attempt["status"]} · {attempt["qa_name"]}', expanded=True):
            st.markdown(retest_markdown([dict(retests=[attempt])]))
            if attempt.get('evidence'):
                display_evidence(attempt['evidence'], caption_prefix=f'Reteste {attempt["number"]} · ')
            else:
                st.caption('Nenhuma imagem anexada nesta tentativa.')


def _report_evidence(scenarios):
    return [ev for s in scenarios
            for ev in (execution_defect_evidence(s) + s.get('bug', {}).get('evidence', [])
                       + [e for a in s.get('retests', []) for e in a['evidence']])]


def report_images(scenarios):
    return {ev['id']: base64.b64decode(ev['data']) for ev in _report_evidence(scenarios)}


def report_image_ids(scenarios):
    """Ids das imagens do relatório, sem decodificar nada (usado para saber se o PDF ficou desatualizado)."""
    return sorted({ev['id'] for ev in _report_evidence(scenarios)})


PDF_STORE_LIMIT_BYTES = 200 * 1024 * 1024


def pdf_signature(markdown_text, scenarios, **fields):
    """Impressão digital de tudo que altera o PDF. As imagens entram pelo id (cada id tem sempre os mesmos bytes)."""
    logos = tuple(hashlib.blake2b(blob, digest_size=8).hexdigest() if blob else '' for blob in (client_logo, company_logo))
    return (markdown_text, tuple(report_image_ids(scenarios)), tuple(sorted(fields.items())),
            qa_name, project_name, sprint, pdf_date, card_code, card_link, logos)


def pdf_on_demand(slot, build, signature, *, generate_label, download_label, file_name, error_text, missing_text,
                  container=None, disabled=False, full_width=False):
    """PDF só é gerado quando a pessoa pede. Depois fica disponível para baixar até o conteúdo mudar."""
    store = st.session_state.setdefault('_pdf_store', {})
    fingerprint = hashlib.blake2b(repr(signature).encode('utf-8'), digest_size=16).hexdigest()
    entry = store.get(slot)
    current = entry is not None and entry['sig'] == fingerprint
    with (container if container is not None else st.container()):
        note = st.empty()
        if entry is not None and not current:
            note.caption('O conteúdo mudou desde que este PDF foi gerado. Gere novamente para baixar a versão atual.')
        placeholder = st.empty()
        if not current:
            label = generate_label if entry is None else 'Gerar PDF novamente'
            if placeholder.button(label, key='pdfgen_' + slot, disabled=disabled, use_container_width=full_width):
                try:
                    with st.spinner('Gerando PDF...'):
                        data = build()
                    store[slot] = dict(sig=fingerprint, data=data)
                    while len(store) > 1 and sum(len(item['data']) for item in store.values()) > PDF_STORE_LIMIT_BYTES:
                        store.pop(next(iter(store)))
                    current = True
                    note.empty()
                except ImportError:
                    placeholder.warning(missing_text)
                except Exception:
                    placeholder.error(error_text)
        if current:
            placeholder.download_button(download_label, store[slot]['data'], file_name=file_name, mime='application/pdf',
                                        key='pdfdl_' + slot, disabled=disabled, use_container_width=full_width)


def retest_csv(scenarios):
    buffer = io.StringIO(newline='')
    writer = csv.writer(buffer, quoting=csv.QUOTE_ALL)
    codes = {row['id']: f'CT{index+1:03d}' for index, row in enumerate(scenarios)}
    writer.writerow(['Cenário', 'Defeito', 'Bug Jira/Azure', 'Tentativa', 'Data (UTC)', 'Status',
                     'QA', 'Projeto', 'Sprint', 'Ambiente', 'Versão',
                     'Resultado esperado', 'Resultado obtido', 'Evidências'])
    for s in scenarios:
        for a in s.get('retests', []):
            values = [codes[s['id']], a['scenario_title'], a['bug_title'],
                      f'{a["number"]}º', a['saved_at'], a['status'], a['qa_name'],
                      a['project_name'], a['sprint'], a['environment'], a['version'],
                      a['expected'], a['actual']]
            writer.writerow([csv_value(v) for v in values] + [csv_value('; '.join(e['name'] for e in a['evidence']))])
    return ('\ufeff' + buffer.getvalue()).encode('utf-8')


def retest_summary_rows(scenarios):
    """Uma linha por item retestado: quantas tentativas e todos os resultados obtidos."""
    rows = []
    codes = {row['id']: f'CT{index+1:03d}' for index, row in enumerate(scenarios)}
    for s in scenarios:
        attempts = s.get('retests', [])
        if not attempts:
            continue
        rows.append({
            'Cenário': f'{codes[s["id"]]} · {s["title"]}',
            'Defeito': attempts[0]['bug_title'],
            'Card do bug': attempts[0]['external_ref'] or attempts[0].get('external_link') or '-',
            'Vezes retestado': len(attempts),
            'Resultados (em ordem)': ' → '.join(f'{a["number"]}º {a["status"]}' for a in attempts),
            'Situação atual': defect_status(s),
            'Último reteste (UTC)': attempts[-1]['saved_at'][:19].replace('T', ' '),
            'Último QA': attempts[-1]['qa_name'],
        })
    return rows


def retest_attempt_rows(scenarios):
    """Uma linha por tentativa de reteste, na ordem em que foram registradas."""
    rows = []
    codes = {row['id']: f'CT{index+1:03d}' for index, row in enumerate(scenarios)}
    for s in scenarios:
        for a in s.get('retests', []):
            rows.append({
                'Cenário': f'{codes[s["id"]]} · {s["title"]}',
                'Tentativa': f'{a["number"]}º',
                'Resultado': a['status'],
                'Data (UTC)': a['saved_at'][:19].replace('T', ' '),
                'QA': a['qa_name'],
                'Ambiente': a['environment'] or '-',
                'Versão': a['version'] or '-',
                'Resultado obtido': a['actual'],
                'Evidências': '; '.join(e['name'] for e in a['evidence']) or '-',
            })
    return rows


def defect_markdown(s, *, qa_name='', project_name='', sprint='', criteria=None, evidence_refs=False, scenario_code=''):
    """Relatório de defeito montado a partir dos campos editáveis, não do cenário bruto."""
    criteria = criteria or []
    bug = ensure_bug(s)
    linked = ', '.join(f'CA{i+1:02d}' for i in s.get('criterion_ids', []) if 0 <= i < len(criteria))
    steps = [line.strip() for line in bug['steps'].splitlines() if line.strip()]
    bug_code = bug['external_ref'].strip()
    bug_link = bug.get('external_link', '').strip()
    card_text = f'[{bug_code}]({bug_link})' if bug_code and bug_link else (bug_code or bug_link or '-')
    lines = [
        f'## Defeito — {bug["title"]}',
        '',
        f'**Projeto:** {project_name or "-"} | **Sprint:** {sprint or "-"} | **QA:** {qa_name or "-"}',
        f'**Severidade:** {bug["severity"]} | **Ambiente:** {bug["environment"] or "-"}',
        f'**Situação do defeito:** {defect_status(s)} | **Card do bug:** {card_text}',
        f'**Cenário de origem:** ' + (f'{scenario_code} · ' if scenario_code else '') + f'{s["kind"]} · Prioridade {s["priority"]}' + (f' · Critérios: {linked}' if linked else ''),
        '',
        '**Pré-condições:**',
        bug['precondition'] or '-',
        '',
        '**Passos para reproduzir:**',
        *[f'{n}. {step}' for n, step in enumerate(steps, 1)],
        '',
        f'**Resultado esperado:** {bug["expected"] or "-"}',
        f'**Resultado obtido:** {bug["actual"] or "-"}',
    ]
    for label, images in [('Evidências da execução', execution_defect_evidence(s)),
                          ('Evidências extras do defeito', bug.get('evidence', []))]:
        if images:
            lines += ['', f'**{label}:**']
            for ev in images:
                lines.append(f'- {ev["name"]}')
                if evidence_refs:
                    lines.append(f'[[QA_EVIDENCE:{ev["id"]}]]')
    if s.get('retests'):
        lines += ['', '## Histórico de retestes', retest_markdown([s], evidence_refs=evidence_refs)]
    return '\n'.join(lines)


def defect_tool_export(failed, tool, *, project_name='', sprint=''):
    """CSV de defeitos no layout de importação do Jira ou do Azure DevOps."""
    if tool not in BUG_TOOL_EXPORTS:
        raise ValueError('Ferramenta de exportação de defeitos não suportada.')
    buffer = io.StringIO(newline='')
    writer = csv.writer(buffer, delimiter=',', quoting=csv.QUOTE_ALL)

    def description(bug, scenario):
        steps = [line.strip() for line in bug['steps'].splitlines() if line.strip()]
        parts = [f'Pré-condições: {bug["precondition"] or "-"}', '', 'Passos para reproduzir:']
        parts += [f'{n}. {step}' for n, step in enumerate(steps, 1)]
        parts += ['', f'Resultado esperado: {bug["expected"] or "-"}',
                  f'Resultado obtido: {bug["actual"] or "-"}',
                  f'Sprint: {sprint or "-"}']
        images = execution_defect_evidence(scenario) + bug.get('evidence', [])
        parts += ['', 'Evidências: ' + '; '.join(image['name'] for image in images)]
        return '\n'.join(parts)

    if tool == 'Jira':
        writer.writerow(['Summary', 'Issue Type', 'Priority', 'Severity', 'Environment', 'Description', 'Labels'])
        for s in failed:
            bug = ensure_bug(s)
            writer.writerow([csv_value(v) for v in
                             [bug['title'], 'Bug', s['priority'], bug['severity'],
                              bug['environment'], description(bug, s) + '\n' + retest_markdown([s]), project_name]])
    else:  # Azure DevOps
        writer.writerow(['Work Item Type', 'Title', 'Priority', 'Severity', 'Repro Steps', 'System Info', 'Tags'])
        for s in failed:
            bug = ensure_bug(s)
            writer.writerow([csv_value(v) for v in
                             ['Bug', bug['title'], s['priority'], bug['severity'],
                              description(bug, s) + '\n' + retest_markdown([s]), bug['environment'], project_name]])
    return ('﻿' + buffer.getvalue()).encode('utf-8')


def scenario_markdown(scenarios, fmt, title='Cenários de Teste', execution=False):
    out = [f'## {title}', '']
    for index, s in enumerate(scenarios, 1):
        out += [f'### CT{index:03d} — {s["title"]}',
                f'**Tipo:** {s["kind"]} | **Prioridade:** {s["priority"]}',
                f'**Pré-condição:** {s["precondition"]}', '']
        steps = [line.strip() for line in s['steps'].splitlines() if line.strip()]
        flow = s.get('flow')
        if flow is not None:
            for n, step in enumerate(flow, 1):
                out += [f'**Etapa {n}:** {step["action"] or "-"}', f'**Resultado esperado:** {step["expected"] or "-"}']
                if execution:
                    out += [f'**Status da etapa:** {step["status"]}', f'**Observações:** {step["observations"] or "-"}']
                    for ev in step.get('evidence', []):
                        out += [f'**Evidência:** {ev["name"]}', f'[[QA_EVIDENCE:{ev["id"]}]]']
                out.append('')
        elif fmt == 'bdd':
            out += ['```gherkin', f'Cenário: {s["title"]}', f'  Dado {s["precondition"]}']
            for n, step in enumerate(steps):
                out.append(f'  {"Quando" if n == 0 else "E"} {step}')
            out += [f'  Então {s["expected"]}', '```']
        elif fmt in ('steps', 'e2e'):
            out += [f'{n}. {step}' for n, step in enumerate(steps, 1)]
            out += [f'**Resultado esperado:** {s["expected"]}']
        else:
            out += [f'{"; ".join(steps)}. **Resultado esperado:** {s["expected"]}']
        if execution:
            out += ['', f'**Status atual:** {effective_status(s)}', f'**Execução original:** {s["status"]}', f'**Observações:** {s["observations"] or "-"}']
            for ev in ([] if flow is not None else s.get('evidence', [])):
                out += [f'**Evidência:** {ev["name"]}', f'[[QA_EVIDENCE:{ev["id"]}]]']
        if execution and s.get('retests'):
            out += ['', retest_markdown([s], evidence_refs=True)]
        out.append('')
    return '\n'.join(out)


GHERKIN_KEYS = {'dado': 'given', 'quando': 'when', 'então': 'then', 'entao': 'then'}


def scenario_to_gherkin(s):
    lines, pre = [], [l.strip() for l in s['precondition'].splitlines() if l.strip()]
    steps = [l.strip() for l in s['steps'].splitlines() if l.strip()]
    exp = [l.strip() for l in s['expected'].splitlines() if l.strip()]
    for word, items in (('Dado', pre), ('Quando', steps), ('Então', exp)):
        lines += [f'{word if n == 0 else "E"} {item}' for n, item in enumerate(items)]
    return '\n'.join(lines)


def gherkin_to_fields(text):
    parts, section = {'given': [], 'when': [], 'then': []}, 'given'
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.lower().startswith(('cenário:', 'cenario:')):
            continue
        word, _, rest = line.partition(' ')
        key = word.lower().rstrip(':')
        if key in GHERKIN_KEYS:
            section, line = GHERKIN_KEYS[key], rest.strip()
        elif key in ('e', 'mas'):
            line = rest.strip()
        parts[section].append(line)
    return {'precondition': '\n'.join(parts['given']), 'steps': '\n'.join(parts['when']),
            'expected': '\n'.join(parts['then'])}


def steps_to_numbered(steps):
    return '\n'.join(f'{n}. {l.strip()}' for n, l in enumerate([l for l in steps.splitlines() if l.strip()], 1))


def numbered_to_steps(text):
    return '\n'.join(re.sub(r'^\s*\d+\s*[.)\-]\s*', '', l).strip() for l in text.splitlines() if l.strip())


def steps_to_summary(steps):
    return '; '.join(l.strip() for l in steps.splitlines() if l.strip())


def summary_to_steps(text):
    return '\n'.join(p.strip().rstrip('.') for p in re.split(r';|\n', text) if p.strip())


def execution_counts(scenarios):
    return {status: sum(effective_status(s) == status for s in scenarios) for status in STATUSES}


def sprint_summary(scenarios):
    """Aggregated numbers for the sprint panel shown in the app and the PDF."""
    counts = execution_counts(scenarios)
    total = len(scenarios)
    executed = total - counts['Não executado']
    return dict(total=total, executed=executed, pending=counts['Não executado'], counts=counts,
                pass_rate=round(100 * counts['Aprovado'] / executed) if executed else 0)


def status_report_rows(entries):
    """Uma linha por US, só com total e status (considera o resultado dos retestes)."""
    rows = []
    for index, entry in enumerate(entries):
        counts = execution_counts(entry['scenarios'])
        progress = [e2e_progress(item) for item in entry['scenarios'] if item.get('flow') is not None]
        rows.append(dict(name=f'{index + 1}. {us_display_name(entry, "US sem nome")}', total=len(entry['scenarios']),
                         aprovados=counts['Aprovado'], reprovados=counts['Reprovado'],
                         bloqueados=counts['Bloqueado'], pendentes=counts['Não executado'],
                         e2e_ok=sum(ok for ok, _ in progress), e2e_total=sum(total for _, total in progress)))
    return rows


def status_report_totals(rows):
    total = sum(r['total'] for r in rows)
    executed = total - sum(r['pendentes'] for r in rows)
    approved = sum(r['aprovados'] for r in rows)
    return dict(total=total, aprovados=approved, reprovados=sum(r['reprovados'] for r in rows),
                bloqueados=sum(r['bloqueados'] for r in rows), pendentes=sum(r['pendentes'] for r in rows),
                e2e_ok=sum(r['e2e_ok'] for r in rows), e2e_total=sum(r['e2e_total'] for r in rows),
                executed=executed, exec_pct=round(100 * executed / total) if total else 0,
                pass_pct=round(100 * approved / executed) if executed else 0)


def status_report_text(rows, totals, *, project_name='', sprint='', qa_name='', report_date=''):
    title = 'Status Report de QA'
    context = ' · '.join(part for part in (project_name.strip(), sprint.strip()) if part)
    lines = [f'{title}{" — " + context if context else ""}']
    meta = [part for part in (f'Data: {report_date.strip()}' if report_date.strip() else '',
                              f'QA: {qa_name.strip()}' if qa_name.strip() else '') if part]
    if meta:
        lines.append(' | '.join(meta))
    lines += ['', 'RESUMO GERAL',
              f'Total de cenários: {totals["total"]}',
              f'Aprovados: {totals["aprovados"]}',
              f'Reprovados: {totals["reprovados"]}',
              f'Bloqueados: {totals["bloqueados"]}',
              f'Não executados: {totals["pendentes"]}',
              f'Executados: {totals["executed"]} de {totals["total"]} ({totals["exec_pct"]}%) · '
              f'Aprovação sobre os executados: {totals["pass_pct"]}%',
              ]
    if totals['e2e_total']:
        lines.append(f'Etapas dos testes E2E aprovadas: {totals["e2e_ok"]} de {totals["e2e_total"]}')
    lines += ['', 'POR US']
    for r in rows:
        line = (f'{r["name"]}: {r["total"]} cenário(s) | Aprovados {r["aprovados"]} | '
                f'Reprovados {r["reprovados"]} | Bloqueados {r["bloqueados"]} | Não executados {r["pendentes"]}')
        if r['e2e_total']:
            line += f' | Etapas E2E aprovadas {r["e2e_ok"]}/{r["e2e_total"]}'
        lines.append(line)
    return '\n'.join(lines)


TOOL_EXPORTS = ('Xray (Jira)', 'TestRail', 'Azure DevOps')


def tool_export(scenarios, tool, *, qa_name='', project_name='', sprint='', criteria=None):
    """CSV imports in the column layout expected by common test management tools."""
    if tool not in TOOL_EXPORTS:
        raise ValueError('Ferramenta de exportação não suportada.')
    buffer = io.StringIO(newline='')
    writer = csv.writer(buffer, delimiter=',', quoting=csv.QUOTE_ALL)

    def rows_of(scenario):
        return [line.strip() for line in scenario['steps'].splitlines() if line.strip()]

    def references(scenario):
        return ', '.join(f'CA{i + 1:02d}' for i in scenario.get('criterion_ids', [])
                         if criteria is not None and 0 <= i < len(criteria))

    if tool == 'Xray (Jira)':
        writer.writerow(['Test Summary', 'Test Type', 'Steps', 'Step', 'Action', 'Data', 'Result'])
        for s in scenarios:
            steps = rows_of(s)
            for n, step in enumerate(steps, 1):
                writer.writerow([csv_value(value) for value in
                                 [s['title'], 'Manual', str(len(steps)), f'Step {n}', step, '',
                                  s['expected'] if n == len(steps) else '']])
    elif tool == 'TestRail':
        writer.writerow(['Title', 'Section', 'References', 'Priority', 'Preconditions', 'Steps', 'Expected Result'])
        for s in scenarios:
            steps = rows_of(s)
            writer.writerow([csv_value(value) for value in
                             [s['title'], project_name, references(s), s['priority'], s['precondition'],
                              '\n'.join(f'{n}. {step}' for n, step in enumerate(steps, 1)), s['expected']]])
    else:  # Azure DevOps
        writer.writerow(['Title', 'Step', 'Step Type', 'Action', 'Expected result'])
        for s in scenarios:
            steps = rows_of(s)
            for n, step in enumerate(steps, 1):
                writer.writerow([csv_value(value) for value in
                                 [s['title'], n, 'Action', step,
                                  s['expected'] if n == len(steps) else '']])
    return ('\ufeff' + buffer.getvalue()).encode('utf-8')


def csv_value(value):
    # Protect spreadsheet users against formulas from story/user-provided fields.
    text = str(value)
    return "'" + text if text.lstrip().startswith(('=', '+', '-', '@')) else text


def export_csv(scenarios, *, qa_name='', project_name='', sprint='', criteria=None):
    buffer = io.StringIO(newline='')
    writer = csv.writer(buffer, delimiter=',', quoting=csv.QUOTE_ALL)
    writer.writerow(['Código', 'Título', 'Tipo', 'Prioridade', 'Pré-condições', 'Passos',
                     'Resultado esperado', 'Status', 'Observações', 'Evidências',
                     'QA', 'Projeto', 'Sprint', 'Critérios vinculados'])
    for index, s in enumerate(scenarios):
        links = [criteria[i] for i in s.get('criterion_ids', [])
                 if criteria is not None and 0 <= i < len(criteria)]
        writer.writerow([csv_value(value) for value in [f'CT{index+1:03d}', s['title'], s['kind'], s['priority'],
                         s['precondition'], s['steps'], s['expected'], effective_status(s), s['observations'],
                         '; '.join(e['name'] for e in s.get('evidence', [])),
                         qa_name, project_name, sprint, '\n'.join(links)]])
    return ('\ufeff' + buffer.getvalue()).encode('utf-8')


def save_snapshot(store, payload, identifier=None):
    payload = json.loads(json.dumps(payload))
    record = new_snapshot_record(payload)
    if identifier:
        record['id'] = identifier
    for index, existing in enumerate(store):
        if existing['id'] == record['id']:
            store[index] = record
            break
    else:
        store.append(record)
    return record['id']


def list_snapshots(store, project='', sprint=''):
    rows = [(record['id'], record['saved_at'], record.get('project', ''), record.get('sprint', ''),
             (record.get('payload') or {}).get('us_name', '')) for record in store]
    return [dict(id=r[0], saved_at=r[1], project=r[2], sprint=r[3], us_name=r[4]) for r in rows
            if project.casefold() in r[2].casefold() and sprint.casefold() in r[3].casefold()]


def load_snapshot(store, identifier):
    record = next((item for item in store if item['id'] == identifier), None)
    if record is None:
        raise ValueError('Registro não encontrado.')
    # Cópia desconectada: abrir a versão não altera os registros vivos.
    return json.loads(json.dumps(record['payload']))


def delete_snapshot(store, identifier):
    store[:] = [item for item in store if item['id'] != identifier]


# --------------------------- Histórico portátil --------------------------- #
# O arquivo .qahub é um ZIP com um JSON dentro. Ele carrega todas as versões
# salvas (cenários, defeitos, retestes e imagens em base64) para que cada QA
# leve o próprio histórico, inclusive no app publicado online.
HISTORY_FORMAT = 'qahub-history'


def history_store():
    """Lista de versões da sessão atual; cada QA leva o histórico no arquivo .qahub."""
    return st.session_state.setdefault('portable_history', [])


def new_snapshot_record(payload):
    return dict(id=uuid.uuid4().hex, saved_at=datetime.now(timezone.utc).isoformat(),
                project=payload.get('project_name', ''), sprint=payload.get('sprint', ''),
                payload=payload)


def export_history_bytes(store):
    records = [dict(id=record['id'], saved_at=record['saved_at'], project=record.get('project', ''),
                    sprint=record.get('sprint', ''), payload=record.get('payload')) for record in store]
    buffer = io.BytesIO()
    with zipfile.ZipFile(buffer, 'w', zipfile.ZIP_DEFLATED) as archive:
        archive.writestr('qahub-history.json', json.dumps(
            dict(format=HISTORY_FORMAT, version=1, app='QAhub', snapshots=records),
            ensure_ascii=False))
    return buffer.getvalue()


def import_history_bytes(data):
    if isinstance(data, str):
        data = data.encode()
    try:
        with zipfile.ZipFile(io.BytesIO(data)) as archive:
            content = archive.read('qahub-history.json')
    except (zipfile.BadZipFile, KeyError) as exc:
        raise ValueError('Este arquivo não é um histórico do QAhub (.qahub).') from exc
    try:
        document = json.loads(content)
        if document.get('format') != HISTORY_FORMAT:
            raise ValueError('formato desconhecido')
        records = document.get('snapshots')
        if not isinstance(records, list):
            raise ValueError('lista de versões ausente')
        cleaned = []
        for record in records:
            if not isinstance(record, dict) or not record.get('id') \
                    or not isinstance(record.get('payload'), dict):
                raise ValueError('versão inválida dentro do arquivo')
            cleaned.append(dict(id=str(record['id']), saved_at=str(record.get('saved_at', '')),
                                project=str(record.get('project', '')),
                                sprint=str(record.get('sprint', '')),
                                payload=record['payload']))
    except (json.JSONDecodeError, TypeError, AttributeError) as exc:
        raise ValueError('Arquivo de histórico inválido ou corrompido.') from exc
    return cleaned


def merge_snapshots(store, records):
    # Importa sem duplicar: versões com o mesmo id já presentes são ignoradas.
    known = {entry['id'] for entry in list_snapshots(store)}
    added = 0
    for record in records:
        if record['id'] in known:
            continue
        store.append(record)
        known.add(record['id'])
        added += 1
    return added


