# Endereços aceitos para o Azure OpenAI (cada empresa tem o seu subdomínio).
AZURE_HOST_SUFFIXES = ('.openai.azure.com', '.cognitiveservices.azure.com', '.services.ai.azure.com')


def validate_azure_endpoint(endpoint):
    """Aceita só endereços oficiais do Azure, por https, para o servidor não ser apontado a endereços internos."""
    endpoint = (endpoint or '').strip()
    if not endpoint:
        raise ValueError('Informe o endpoint do Azure.')
    message = ('Endpoint do Azure inválido. Use o endereço do seu recurso, por exemplo '
               'https://minha-empresa.openai.azure.com')
    try:
        parts = urlparse(endpoint)
        host = (parts.hostname or '').lower()
        port = parts.port
    except ValueError as exc:
        raise ValueError(message) from exc
    if (parts.scheme.lower() != 'https' or parts.username or parts.password or port not in (None, 443)
            or parts.path not in ('', '/') or parts.params or parts.query or parts.fragment
            or not re.fullmatch(r'[a-z0-9-]+(\.[a-z0-9-]+)*', host)
            or not any(host.endswith(suffix) and len(host) > len(suffix) for suffix in AZURE_HOST_SUFFIXES)):
        raise ValueError(message)
    return f'https://{host}'


def resolve_ai_base_url(provider, typed=''):
    """Endereço realmente usado: fixo por provedor; só o Azure aceita endereço digitado (validado)."""
    if provider == 'Azure OpenAI':
        return validate_azure_endpoint(typed)
    info = AI_PROVIDERS.get(provider)
    if info is None:
        raise ValueError('Provedor de IA desconhecido.')
    return info['base_url']


def make_ai_client(provider, api_key, base_url='', azure_version='2024-10-21'):
    from openai import OpenAI, AzureOpenAI
    endpoint = resolve_ai_base_url(provider, base_url)
    if provider == 'Azure OpenAI':
        return AzureOpenAI(api_key=api_key, azure_endpoint=endpoint, api_version=azure_version or '2024-10-21')
    return OpenAI(api_key=api_key or 'sem-chave', base_url=endpoint)


def extract_json(content):
    content = (content or '').strip()
    fence = re.search(r'```(?:json)?\s*(.*?)```', content, re.S)
    if fence:
        content = fence.group(1)
    start, end = content.find('{'), content.rfind('}')
    if start < 0 or end < start:
        raise ValueError('Resposta sem JSON.')
    return json.loads(content[start:end + 1])


def structured_with_ai(text, api_key, model, base_url, criteria, provider='OpenAI', azure_version=''):
    client = make_ai_client(provider, api_key, base_url, azure_version)
    messages = [{'role': 'system', 'content': 'Você é um QA sênior. Retorne somente JSON com scenarios: lista de objetos com title, precondition, steps (texto com uma ação por linha), expected, kind (Positivo, Negativo ou Limite), criterion_ids (índices zero-based). Não invente regras; marque incertezas para revisão. Critérios: ' + json.dumps(criteria, ensure_ascii=False)},
                {'role': 'user', 'content': text}]
    try:
        response = client.chat.completions.create(model=model, temperature=0.3, messages=messages,
                                                  response_format={'type': 'json_object'})
    except Exception as exc:
        if getattr(exc, 'status_code', None) not in (400, 422):
            raise
        response = client.chat.completions.create(model=model, temperature=0.3, messages=messages)
    data = extract_json(response.choices[0].message.content)
    records = data.get('scenarios')
    if not isinstance(records, list) or not records:
        raise ValueError('Resposta sem cenários estruturados.')
    result = []
    for item in records:
        if not isinstance(item, dict) or not all(isinstance(item.get(k), str) and item[k].strip() for k in ('title', 'precondition', 'steps', 'expected')):
            raise ValueError('Cenário incompleto na resposta.')
        ids = item.get('criterion_ids', [])
        if not isinstance(ids, list):
            raise ValueError('Vínculos inválidos na resposta.')
        result.append(new_scenario(item['title'], precondition=item['precondition'], steps=item['steps'],
                                   expected=item['expected'], kind=item.get('kind') if item.get('kind') in KINDS else 'Positivo',
                                   criterion_ids=[i for i in ids if type(i) is int and 0 <= i < len(criteria)]))
    return result


def render_e2e_execution(s, prefix):
    """Execução de um teste E2E: status, observação e evidência por etapa."""
    st.write('**Pré-condições:**', s['precondition'] or '-')
    editable = e2e_steps_editable(s)
    if not editable:
        st.info('Defeito aberto ou reteste registrado: as etapas ficam travadas para preservar a falha original. '
                'Use a aba Reteste.')
    step_changes = {}
    for n, step in enumerate(s['flow'], 1):
        sk = f'{prefix}_s{step["id"]}'
        st.markdown(f'**Etapa {n} · {step["action"] or "(sem ação)"}**')
        st.caption(f'Resultado esperado: {step["expected"] or "-"}')
        status = st.selectbox('Status da etapa', STATUSES, index=STATUSES.index(step['status']),
                              key=sk+'_status', disabled=not editable)
        if step.get('auto_blocked'):
            st.caption('Bloqueada automaticamente porque uma etapa anterior reprovou.')
        notes = st.text_area('Observações / resultado obtido', value=step['observations'], key=sk+'_notes',
                             disabled=not editable)
        uploads = st.file_uploader('Evidências da etapa (PNG/JPG)', type=['png', 'jpg', 'jpeg'],
                                   accept_multiple_files=True, key=sk+'_evidence', disabled=not editable)
        removed = []
        for ev in step.get('evidence', []):
            display_evidence([ev])
            if st.checkbox('Remover evidência ao salvar', key=sk+'_remove_'+ev['id'], disabled=not editable):
                removed.append(ev['id'])
        step_changes[step['id']] = dict(status=status, observations=notes, remove_evidence=removed,
                                        evidence=[dict(name=upload.name, data=base64.b64encode(upload.getvalue()).decode())
                                                  for upload in uploads or []])
        st.divider()
    change = dict(steps=step_changes, status=effective_status(s))
    if s.get('retests'):
        latest_id = s['retests'][-1]['id']
        change['status'] = st.selectbox('Status do teste (após reteste)', STATUSES, index=STATUSES.index(effective_status(s)),
                                        key=prefix+'_status_'+latest_id, disabled=not execution_status_editable(s))
    else:
        st.write(f'**Status do teste (calculado pelas etapas):** {effective_status(s)}')
    if s.get('bug'):
        st.write(f'**Situação atual:** {effective_status(s)} · **Defeito:** {defect_status(s)}')
    return change


def clear_scenario_widgets():
    for key in list(st.session_state):
        if key.startswith(('sc_', 'exec_', 'suggest_', 'evidence_', 'bug_', 'rt_')):
            del st.session_state[key]


# ------------------------- Várias User Stories (US) ------------------------- #
# Cada US tem texto, critérios, cenários, código/link do card e o registro do
# histórico. Projeto, sprint, QA, data e logos são compartilhados entre as US.
# A US em edição vive nas chaves de sempre (input, criteria, scenarios...);
# ao trocar de US, o conteúdo é guardado na lista e a outra é carregada.
US_TAB_KEYS = ('cen', 'cob', 'exe', 'def', 'ret', 'exp', 'sta', 'his')


def us_new(name=''):
    return dict(id=uuid.uuid4().hex, name=name, input='', criteria=[], scenarios=[],
                card_code='', card_link='', snapshot_id=None)


def us_init():
    if 'us_list' not in st.session_state:
        first = us_new()
        first.update(input=st.session_state.get('input', ''), criteria=st.session_state.get('criteria', []),
                     scenarios=st.session_state.get('scenarios', []),
                     card_code=st.session_state.get('pdf_card_code', ''),
                     card_link=st.session_state.get('pdf_card_link', ''),
                     snapshot_id=st.session_state.get('active_snapshot_id'))
        st.session_state['us_list'] = [first]
        st.session_state['us_current'] = first['id']


def us_current_entry():
    for entry in st.session_state['us_list']:
        if entry['id'] == st.session_state['us_current']:
            return entry
    return st.session_state['us_list'][0]


def us_sync_out():
    """Guarda na lista o que está sendo editado agora na US atual."""
    st.session_state['us_current'] = us_current_entry()['id']
    us_current_entry().update(
        input=st.session_state.get('input', ''), criteria=st.session_state.get('criteria', []),
        scenarios=st.session_state.get('scenarios', []), card_code=st.session_state.get('pdf_card_code', ''),
        card_link=st.session_state.get('pdf_card_link', ''), snapshot_id=st.session_state.get('active_snapshot_id'))


def us_load_in(entry):
    """Coloca a US escolhida nas chaves de trabalho que as abas usam."""
    clear_scenario_widgets()
    st.session_state['execution_form_revision'] = st.session_state.get('execution_form_revision', 0) + 1
    st.session_state['us_current'] = entry['id']
    st.session_state['input'] = entry['input']
    st.session_state['criteria'] = entry['criteria']
    st.session_state['scenarios'] = entry['scenarios']
    st.session_state['pdf_card_code'] = entry['card_code']
    st.session_state['pdf_card_link'] = entry['card_link']
    if entry.get('snapshot_id'):
        st.session_state['active_snapshot_id'] = entry['snapshot_id']
    else:
        st.session_state.pop('active_snapshot_id', None)
    for tab_key in US_TAB_KEYS:
        st.session_state['us_name_input_' + tab_key] = entry['name']
        st.session_state['us_delete_confirm_' + tab_key] = False
    for key in ('requirements_notice', 'draft_notice', 'last_draft_id', 'execution_saved', 'retest_saved',
                'defect_evidence_saved'):
        st.session_state.pop(key, None)


def us_display_name(entry, fallback=''):
    name = (entry.get('name') or '').strip() or (entry.get('card_code') or '').strip()
    if not name:
        first = next((line.strip() for line in (entry.get('input') or '').splitlines() if line.strip()), '')
        name = first[:45] + ('…' if len(first) > 45 else '')
    return name or fallback


def us_label(entry):
    index = st.session_state['us_list'].index(entry)
    total = len(entry.get('scenarios') or [])
    return f'{index + 1}. {us_display_name(entry, "US sem nome")} · {total} cenário(s)'


def us_forget_snapshot(snapshot_id):
    """Uma versão do histórico foi excluída: nenhuma US deve continuar apontando para ela."""
    for entry in st.session_state.get('us_list', []):
        if entry.get('snapshot_id') == snapshot_id:
            entry['snapshot_id'] = None
    if st.session_state.get('active_snapshot_id') == snapshot_id:
        st.session_state.pop('active_snapshot_id', None)


def us_cb_switch(tab_key):
    us_sync_out()
    target = next((u for u in st.session_state['us_list'] if u['id'] == st.session_state['us_select_' + tab_key]), None)
    if target is not None:
        us_load_in(target)


def us_cb_new():
    us_sync_out()
    entry = us_new()
    st.session_state['us_list'].append(entry)
    us_load_in(entry)
    st.session_state['us_notice'] = 'Nova US criada. Cole a história e clique em Gerar Cenários.'


def us_cb_rename(tab_key):
    us_current_entry()['name'] = (st.session_state.get('us_name_input_' + tab_key) or '').strip()


def us_cb_delete():
    entries = st.session_state['us_list']
    if len(entries) < 2:
        return
    us_sync_out()
    index = entries.index(us_current_entry())
    removed = entries.pop(index)
    target = entries[min(index, len(entries) - 1)]
    us_load_in(target)
    st.session_state['us_notice'] = (f'US "{us_display_name(removed, "sem nome")}" removida do app. '
                                     'Versões já salvas no histórico continuam lá.')


def build_payload(entry):
    return dict(input=entry['input'], criteria=entry['criteria'], scenarios=entry['scenarios'],
                qa_name=st.session_state.get('pdf_qa_name', ''),
                project_name=st.session_state.get('pdf_project_name', ''), sprint=st.session_state.get('pdf_sprint', ''),
                card_code=entry['card_code'], card_link=entry['card_link'],
                pdf_date=st.session_state.get('pdf_date', ''),
                format_label=st.session_state.get('format_label', next(iter(FORMATS))),
                client_logo=base64.b64encode(st.session_state.get('validated_logo') or b'').decode(),
                company_logo=base64.b64encode(st.session_state.get('validated_company_logo') or b'').decode(),
                us_name=us_display_name(entry))


def current_payload():
    us_sync_out()
    return build_payload(us_current_entry())


def us_open_snapshot(payload, snapshot_id=None):
    """Abre uma versão do histórico como US: reaproveita a que já está aberta, usa a atual se estiver vazia ou cria outra."""
    us_sync_out()
    existing = next((u for u in st.session_state['us_list'] if snapshot_id and u.get('snapshot_id') == snapshot_id), None)
    if existing is not None:
        us_load_in(existing)
        st.session_state['us_notice'] = (f'Esta versão já estava aberta como "{us_display_name(existing, "US sem nome")}". '
                                         'Mudei para ela e mantive suas alterações não salvas.')
        return
    target = us_current_entry()
    if target['scenarios'] or target['input'].strip():
        target = us_new()
        st.session_state['us_list'].append(target)
    target.update(input=payload.get('input', ''), criteria=payload.get('criteria', []),
                  scenarios=payload.get('scenarios', []), card_code=payload.get('card_code', ''),
                  card_link=payload.get('card_link', ''), snapshot_id=snapshot_id,
                  name=payload.get('us_name', ''))
    for key in ('qa_name', 'project_name', 'sprint'):
        st.session_state['pdf_' + key] = payload.get(key, '')
    if payload.get('format_label') in FORMATS:
        st.session_state['format_label'] = payload['format_label']
    st.session_state['pdf_date'] = payload.get('pdf_date') or datetime.now().strftime('%d/%m/%Y')
    st.session_state['validated_logo'] = base64.b64decode(payload.get('client_logo', '')) or None
    st.session_state.pop('pdf_client_logo', None)
    st.session_state['validated_company_logo'] = base64.b64decode(payload.get('company_logo', '')) or None
    st.session_state.pop('pdf_company_logo', None)
    us_load_in(target)
    st.session_state['us_notice'] = f'Versão aberta como US "{us_display_name(target, "sem nome")}".'


