        st.caption('CSV genérico: ao importar em uma ferramenta de testes, faça o mapeamento das colunas. Imagens ficam no PDF e no histórico; CSV contém os nomes.')
        summary_for_pdf = sprint_summary(scenarios) if include_execution else None
