with tab_status:
    st.subheader('Status Report')
    st.caption('Resumo diário de todas as US abertas no app, só com o total e os status. '
               'Os números consideram o resultado dos retestes.')
    us_sync_out()
    report_rows = status_report_rows(st.session_state['us_list'])
    report_totals = status_report_totals(report_rows)
    if not report_totals['total']:
        st.info('Ainda não há cenários em nenhuma US. Gere os cenários na aba Cenários para montar o resumo.')
    m1, m2, m3, m4, m5 = st.columns(5)
    m1.metric('Total', report_totals['total'])
    m2.metric('Aprovados', report_totals['aprovados'])
    m3.metric('Reprovados', report_totals['reprovados'])
    m4.metric('Bloqueados', report_totals['bloqueados'])
    m5.metric('Não executados', report_totals['pendentes'])
    st.caption(f'Executados: {report_totals["executed"]} de {report_totals["total"]} ({report_totals["exec_pct"]}%) · '
               f'Aprovação sobre os executados: {report_totals["pass_pct"]}%')
    if report_totals['e2e_total']:
        st.caption(f'Etapas dos testes E2E aprovadas: {report_totals["e2e_ok"]} de {report_totals["e2e_total"]}')
    table = [{'US': r['name'], 'Total': r['total'], 'Aprovados': r['aprovados'], 'Reprovados': r['reprovados'],
              'Bloqueados': r['bloqueados'], 'Não executados': r['pendentes']} for r in report_rows]
    table.append({'US': 'Total geral', 'Total': report_totals['total'], 'Aprovados': report_totals['aprovados'],
                  'Reprovados': report_totals['reprovados'], 'Bloqueados': report_totals['bloqueados'],
                  'Não executados': report_totals['pendentes']})
    st.dataframe(table, hide_index=True, use_container_width=True)

    st.subheader('Texto para o e-mail')
    report_text = status_report_text(report_rows, report_totals, project_name=project_name, sprint=sprint,
                                     qa_name=qa_name, report_date=pdf_date)
    text_key = 'status_text_' + hashlib.md5(report_text.encode('utf-8')).hexdigest()[:10]
    final_text = st.text_area('Revise ou ajuste antes de enviar', value=report_text, key=text_key, height=300)
    subject = 'Status Report de QA' + ''.join(f' - {part.strip()}' for part in (project_name, sprint, pdf_date) if part.strip())
    b1, b2, b3 = st.columns([1.3, 1, 1.3])
    with b1:
        copy_button(final_text, 'status_report', 'Copiar texto do e-mail')
    b2.download_button('Baixar .txt', final_text, file_name='status_report.txt', mime='text/plain', use_container_width=True)
    mailto = f'mailto:?subject={quote(subject, safe="")}&body={quote(final_text, safe="")}'
    if len(mailto) <= 1900:
        b3.markdown(f'<a href="{mailto.replace("&", "&amp;")}" style="display:inline-block;padding:12px 14px;border:1px solid #dfe2e6;'
                    'border-radius:6px;background:#fff;color:#161616;font-weight:600;text-decoration:none;">'
                    'Abrir no e-mail</a>', unsafe_allow_html=True)
    else:
        b3.caption('Texto longo demais para abrir direto no e-mail: use "Copiar texto do e-mail".')
    st.caption(f'Assunto sugerido: {subject}')

with tab_history:
    st.subheader('Histórico por projeto e sprint')
    st.caption('Cada versão salva é uma US. Para abrir uma versão no app, use "Abrir como US".')
    store = history_store()
    imported_message = st.session_state.pop('history_import_done', None)
    if imported_message:
        st.success(imported_message)
    st.warning('**Modo arquivo portátil:** o histórico existe apenas nesta sessão. '
               'Baixe o arquivo .qahub abaixo antes de fechar a página e abra-o aqui na próxima vez — '
               'senão o que foi feito hoje é perdido.')
    uploaded_history = st.file_uploader('Abrir meu histórico (.qahub)', type=['qahub', 'zip'], key='history_file')
    if uploaded_history is not None:
        upload_token = f'{uploaded_history.name}:{uploaded_history.size}'
        if st.session_state.get('history_import_token') != upload_token:
            try:
                st.session_state['history_import_token'] = upload_token
                st.session_state['history_import_pending'] = import_history_bytes(uploaded_history.getvalue())
            except ValueError as exc:
                st.session_state.pop('history_import_pending', None)
                st.error(str(exc))
    pending_import = st.session_state.get('history_import_pending')
    if pending_import is not None and uploaded_history is not None:
        st.info(f'Arquivo **{uploaded_history.name}**: {len(pending_import)} versão(ões) encontrada(s).')
        open_latest = st.checkbox('Abrir também a versão mais recente no app', value=True, key='history_import_open')
        if st.button('Importar este histórico', type='primary'):
            try:
                added = merge_snapshots(store, pending_import)
                done = f'Histórico importado: {added} versão(ões) adicionada(s).'
                if open_latest and pending_import:
                    latest = max(pending_import, key=lambda record: record.get('saved_at', ''))
                    st.session_state['pending_restore_id'] = latest['id']
                    st.session_state['pending_restore'] = json.loads(json.dumps(latest['payload']))
                    done += ' A versão mais recente foi aberta no app.'
                st.session_state['history_import_done'] = done
                st.session_state.pop('history_import_pending', None)
                st.session_state.pop('history_import_token', None)
                st.rerun()
            except (ValueError, TypeError) as exc:
                st.error(f'Não foi possível importar: {exc}')
    save_one, save_all = st.columns(2)
    if save_one.button('Salvar US atual', type='primary', disabled=not scenarios):
        try:
            st.session_state['active_snapshot_id'] = save_snapshot(
                store, current_payload(), st.session_state.get('active_snapshot_id'))
            st.success('US atual salva no histórico (no mesmo registro, se já existia). Baixe o arquivo antes de fechar.')
        except (ValueError, TypeError):
            st.error('Não foi possível salvar o histórico. Tente novamente antes de fechar a página.')
    us_sync_out()
    if save_all.button('Salvar todas as US', disabled=not any(u['scenarios'] for u in st.session_state['us_list'])):
        try:
            saved = 0
            for entry in st.session_state['us_list']:
                if entry['scenarios']:
                    entry['snapshot_id'] = save_snapshot(store, build_payload(entry), entry.get('snapshot_id'))
                    saved += 1
            if us_current_entry().get('snapshot_id'):
                st.session_state['active_snapshot_id'] = us_current_entry()['snapshot_id']
            st.success(f'{saved} US salva(s) no histórico. Baixe o arquivo antes de fechar.')
        except (ValueError, TypeError):
            st.error('Não foi possível salvar o histórico. Tente novamente antes de fechar a página.')
    try:
        all_snapshots = list_snapshots(store)
        snapshots = all_snapshots
        for entry in snapshots:
            with st.expander(f'{entry.get("us_name") or "US sem nome"} · {entry["project"] or "Sem projeto"} · {entry["sprint"] or "Sem sprint"} · {entry["saved_at"][:19].replace("T", " ")} UTC'):
                if st.checkbox('Ver defeitos, retestes e evidências desta versão', key='preview_' + entry['id']):
                    stored = load_snapshot(store, entry['id'])
                    for stored_scenario in stored.get('scenarios', []):
                        if not stored_scenario.get('bug') and not stored_scenario.get('retests'):
                            continue
                        st.markdown('**' + stored_scenario.get('title', 'Cenário') + '**')
                        display_evidence(stored_scenario.get('evidence', []), caption_prefix='Execução original · ')
                        display_evidence(stored_scenario.get('bug', {}).get('evidence', []), caption_prefix='Evidência extra do defeito · ')
                        display_retest_history(stored_scenario)
                a, b = st.columns(2)
                if a.button('Abrir como US', key='load_'+entry['id'], help='Abre esta versão como uma US no app, sem apagar as que já estão abertas.'):
                    st.session_state['pending_restore_id'] = entry['id']
                    st.session_state['pending_restore'] = load_snapshot(store, entry['id'])
                    st.rerun()
                confirm_delete = st.checkbox('Confirmar exclusão', key='confirm_'+entry['id'])
                if b.button('Excluir versão', key='delete_'+entry['id'], disabled=not confirm_delete):
                    delete_snapshot(store, entry['id'])
                    us_forget_snapshot(entry['id'])
                    st.rerun()
        if not snapshots:
            st.caption('Nada no histórico ainda. Clique em "Salvar US atual" para começar.')
        st.divider()
        if all_snapshots:
            label = 'Baixar meu histórico (.qahub) — faça isso antes de fechar a página!'
            history_name = st.text_input('Nome do arquivo do histórico', value='historico_qahub',
                                         key='history_download_name')
            safe_name = re.sub(r'[^\w\-. ]+', '_', (history_name or '').strip()) or 'historico_qahub'
            st.download_button(label, export_history_bytes(store), file_name=f'{safe_name}.qahub',
                               mime='application/zip', type='primary')
            st.caption('Guarde o arquivo com você (pasta, e-mail, pendrive). Na próxima sessão, '
                       'envie-o em "Abrir meu histórico" e tudo volta: cenários, defeitos, retestes e imagens.')
        else:
            st.caption('Salve uma versão para poder baixar o arquivo de histórico.')
    except (ValueError, TypeError) as exc:
        st.error(f'Histórico indisponível: {exc}')


# Caixa de User Stories: aparece no topo de cada aba (logo abaixo das abas), mas é
# desenhada por último para mostrar os números atualizados (ex.: após Gerar Cenários).
def render_us_bar(tab_key, notice):
    with st.container(border=True):
        if notice:
            st.success(notice)
        col_select, col_name, col_new = st.columns([3, 3, 1.4])
        us_labels = {u['id']: us_label(u) for u in st.session_state['us_list']}
        col_select.selectbox('User Story (US) em edição', list(us_labels), key='us_select_' + tab_key,
                             on_change=us_cb_switch, args=(tab_key,), format_func=us_labels.get)
        col_name.text_input('Nome da US', key='us_name_input_' + tab_key, on_change=us_cb_rename, args=(tab_key,),
                            max_chars=120, placeholder='Ex.: US-123 · Login com e-mail e senha')
        col_new.markdown('<div style="height: 1.8rem"></div>', unsafe_allow_html=True)
        col_new.button('Nova US', on_click=us_cb_new, use_container_width=True, key='us_new_' + tab_key)
        st.caption('Projeto, sprint, QA e logos valem para todas as US. Código/link do card, história, cenários, '
                   'execução, defeitos e retestes pertencem a cada US.')
        if len(st.session_state['us_list']) > 1:
            with st.expander('Visão geral das US'):
                overview = []
                for index, entry in enumerate(st.session_state['us_list']):
                    counts = execution_counts(entry['scenarios'])
                    overview.append({'US': f'{index + 1}. {us_display_name(entry, "US sem nome")}',
                                     'Cenários': len(entry['scenarios']), 'Aprovados': counts['Aprovado'],
                                     'Reprovados': counts['Reprovado'], 'Bloqueados': counts['Bloqueado'],
                                     'Não executados': counts['Não executado']})
                st.dataframe(overview, hide_index=True, use_container_width=True)
        with st.expander('Excluir esta US'):
            st.caption('Remove a US do app. Se ela não foi salva no histórico, o trabalho dela é perdido; '
                       'versões já salvas no histórico não são apagadas.')
            confirm_us_delete = st.checkbox('Confirmar exclusão desta US', key='us_delete_confirm_' + tab_key)
            st.button('Excluir US', disabled=not confirm_us_delete or len(st.session_state['us_list']) < 2,
                      on_click=us_cb_delete, key='us_delete_' + tab_key)


us_sync_out()
us_notice = st.session_state.pop('us_notice', None)
for tab_key, slot in us_slots.items():
    st.session_state['us_select_' + tab_key] = st.session_state['us_current']
    st.session_state['us_name_input_' + tab_key] = us_current_entry()['name']
    with slot:
        render_us_bar(tab_key, us_notice)
